import ModalWindow from "../ModalWindow";
import "./TrainerShedule.css";

interface TrainerSheduleProps {
  isOpen: boolean;
  onClose: () => void;
  trainerId: number;
}

const TrainerShedule = ({
  isOpen,
  onClose,
  trainerId,
}: TrainerSheduleProps) => {
  return (
    <ModalWindow isOpen={isOpen} onClose={onClose}>
      <div className="trainer-schedule">
        <h2>Trainer Schedule</h2>
        <p>Trainer ID: {trainerId}</p>
        {/* Тут буде відображення розкладу */}
      </div>
    </ModalWindow>
  );
};

export default TrainerShedule;
